import { requireAdminUser } from "@/lib/server/api-auth";
import { getAdminChatConversation } from "@/lib/server/admin-console";
import { enforceRateLimit, isSafeRouteParam, jsonWithSecurity } from "@/lib/server/security";

export const runtime = "nodejs";

export async function GET(
  request: Request,
  context: { params: Promise<{ id: string }> },
) {
  const rateLimitError = enforceRateLimit(request, {
    scope: "admin-chat-detail",
    maxRequests: 120,
    windowMs: 60_000,
  });
  if (rateLimitError) {
    return rateLimitError;
  }

  const auth = await requireAdminUser(request);
  if (auth instanceof Response) {
    return auth;
  }

  const { id } = await context.params;
  if (!isSafeRouteParam(id, 120)) {
    return jsonWithSecurity({ ok: false, message: "Chat inválido" }, { status: 400 });
  }

  const conversation = await getAdminChatConversation(id);
  if (!conversation) {
    return jsonWithSecurity({ ok: false, message: "Chat no encontrado" }, { status: 404 });
  }

  return jsonWithSecurity({
    ok: true,
    conversation,
  });
}
