function parseJsonRecord(value: string | null | undefined) {
  if (!value) {
    return null;
  }

  try {
    const parsed = JSON.parse(value) as Record<string, unknown>;
    return parsed && typeof parsed === "object" ? parsed : null;
  } catch {
    return null;
  }
}

function toIso(value: Date | string | null | undefined) {
  if (!value) {
    return null;
  }

  return value instanceof Date ? value.toISOString() : new Date(value).toISOString();
}

function buildTaskStatus(count: number) {
  return count > 0 ? "backlog" : "done";
}

function buildTaskPriority(count: number, highThreshold = 1): "low" | "medium" | "high" {
  if (count >= Math.max(3, highThreshold)) {
    return "high";
  }

  if (count > 0) {
    return "medium";
  }

  return "low";
}

async function listAdminChats(): Promise<AdminChatRecord[]> {
  const rows = await prisma.$queryRaw<Array<{
    id: string;
    status: "active" | "closed" | "pending_review";
    applicationId: string;
    companyName: string | null;
    candidateName: string | null;
    messagesCount: number | null;
    reportsCount: number | null;
    warningsCount: number | null;
    lastMessageAt: Date | null;
    updatedAt: Date;
  }>>(Prisma.sql`
    SELECT
      c.id,
      c.status,
      c.application_id AS "applicationId",
      COALESCE(cp."companyName", cu."displayName") AS "companyName",
      COALESCE(pp.nombre, pu."displayName") AS "candidateName",
      COALESCE(mc.messages_count, 0)::int AS "messagesCount",
      COALESCE(mod.reports_count, 0)::int AS "reportsCount",
      COALESCE(mod.warnings_count, 0)::int AS "warningsCount",
      c.last_message_at AS "lastMessageAt",
      c.updated_at AS "updatedAt"
    FROM chat_conversations c
    INNER JOIN "User" cu ON cu.id = c.company_user_id
    INNER JOIN "Profile" cp ON cp."userId" = cu.id
    INNER JOIN "User" pu ON pu.id = c.candidate_user_id
    INNER JOIN "Profile" pp ON pp."userId" = pu.id
    LEFT JOIN (
      SELECT conversation_id, COUNT(*) AS messages_count
      FROM chat_messages
      GROUP BY conversation_id
    ) mc ON mc.conversation_id = c.id
    LEFT JOIN (
      SELECT
        conversation_id,
        COUNT(*) FILTER (WHERE event_type = 'report') AS reports_count,
        COUNT(*) FILTER (WHERE event_type = 'profanity_warning') AS warnings_count
      FROM chat_moderation_events
      GROUP BY conversation_id
    ) mod ON mod.conversation_id = c.id
    ORDER BY c.updated_at DESC
    LIMIT 20
  `);

  return rows.map((row) => ({
    id: row.id,
    status: row.status,
    companyName: row.companyName ?? "Empresa",
    candidateName: row.candidateName ?? "Candidato",
    applicationId: row.applicationId,
    messagesCount: row.messagesCount ?? 0,
    reportsCount: row.reportsCount ?? 0,
    warningsCount: row.warningsCount ?? 0,
    lastMessageAt: toIso(row.lastMessageAt),
    updatedAt: toIso(row.updatedAt) ?? new Date().toISOString(),
  }));
}

async function listAdminInvites(): Promise<AdminInviteRecord[]> {
  const rows = await prisma.$queryRaw<Array<{
    id: string;
    status: AdminInviteRecord["status"];
    requestedStage: string;
    applicationId: string;
    companyName: string | null;
    candidateName: string | null;
    sentAt: Date;
    respondedAt: Date | null;
    rejectCooldownUntil: Date | null;
  }>>(Prisma.sql`
    SELECT
      i.id,
      i.status,
      i.requested_stage AS "requestedStage",
      i.application_id AS "applicationId",
      COALESCE(cp."companyName", cu."displayName") AS "companyName",
      COALESCE(pp.nombre, pu."displayName") AS "candidateName",
      i.sent_at AS "sentAt",
      i.responded_at AS "respondedAt",
      i.reject_cooldown_until AS "rejectCooldownUntil"
    FROM chat_process_invites i
    INNER JOIN "User" cu ON cu.id = i.company_user_id
    INNER JOIN "Profile" cp ON cp."userId" = cu.id
    INNER JOIN "User" pu ON pu.id = i.candidate_user_id
    INNER JOIN "Profile" pp ON pp."userId" = pu.id
    ORDER BY i.sent_at DESC
    LIMIT 20
  `);

  return rows.map((row) => ({
    id: row.id,
    status: row.status,
    requestedStage: row.requestedStage,
    applicationId: row.applicationId,
    companyName: row.companyName ?? "Empresa",
    candidateName: row.candidateName ?? "Candidato",
    sentAt: toIso(row.sentAt) ?? new Date().toISOString(),
    respondedAt: toIso(row.respondedAt),
    rejectCooldownUntil: toIso(row.rejectCooldownUntil),
  }));
}

async function listAdminSessions(): Promise<AdminSessionRecord[]> {
  const rows = await prisma.session.findMany({
    include: {
      user: {
        select: {
          id: true,
          role: true,
          displayName: true,
        },
      },
    },
    orderBy: { createdAt: "desc" },
    take: 20,
  });

  return rows.map((row) => ({
    userId: row.userId,
    displayName: row.user?.displayName ?? row.userId,
    role: row.user?.role ?? "candidate",
    createdAt: row.createdAt.toISOString(),
    expiresAt: row.expiresAt.toISOString(),
    revokedAt: toIso(row.revokedAt),
  }));
}

async function listAdminVerifications(): Promise<AdminVerificationRecord[]> {
  const rows = await prisma.verificationRequest.findMany({
    orderBy: { submittedAt: "desc" },
    take: 20,
  });

  return rows.map((row) => ({
    id: row.id,
    role: row.role,
    status: row.status,
    userId: row.userId,
    notes: row.notes ?? undefined,
    submittedAt: row.submittedAt.toISOString(),
    reviewedAt: toIso(row.reviewedAt),
  }));
}

async function listAdminActivities(options?: {
  type?: string;
  from?: Date | null;
  to?: Date | null;
  limit?: number;
}): Promise<AdminActivityRecord[]> {
  const rows = await prisma.event.findMany({
    where: {
      ...(options?.type ? { type: options.type } : {}),
      happenedAt: {
        ...(options?.from ? { gte: options.from } : {}),
        ...(options?.to ? { lte: options.to } : {}),
      },
    },
    orderBy: { happenedAt: "desc" },
    take: options?.limit ?? 50,
    select: {
      id: true,
      type: true,
      actorRole: true,
      entityId: true,
      pathname: true,
      source: true,
      happenedAt: true,
      metadataJson: true,
    },
  });

  return rows.map((row) => ({
    ...(() => {
      const metadata = parseJsonRecord(row.metadataJson);
      return {
        targetPath: typeof metadata?.requestUrl === "string" ? metadata.requestUrl : row.entityId,
        method: typeof metadata?.method === "string" ? metadata.method : null,
        statusCode: typeof metadata?.statusCode === "number" ? metadata.statusCode : null,
        durationMs: typeof metadata?.durationMs === "number" ? metadata.durationMs : null,
      };
    })(),
    id: row.id,
    type: row.type,
    actorRole: row.actorRole,
    entityId: row.entityId,
    pathname: row.pathname,
    source: row.source,
    happenedAt: row.happenedAt.toISOString(),
  }));
}

