export async function getAdminConsole(options?: {
  activityType?: string;
  activityFrom?: Date | null;
  activityTo?: Date | null;
  activityLimit?: number;
}): Promise<AdminConsolePayload> {
  const [overview, users, jobs, sessions, verifications, errors, chats, invites, activities, trafficAnalytics] = await Promise.all([
    getAdminOverview(),
    listUsersForAdmin(),
    listJobsForAdmin(),
    listAdminSessions(),
    listAdminVerifications(),
    listAdminErrors(),
    listAdminChats(),
    listAdminInvites(),
    listAdminActivities({
      type: options?.activityType,
      from: options?.activityFrom,
      to: options?.activityTo,
      limit: options?.activityLimit,
    }),
    getAdminTrafficAnalytics(),
  ]);

  const privateCandidates = users.filter((item: AdminUserPreview) => item.role === "candidate" && item.profileVisibility === "private").length;
  const unverifiedCompanies = users.filter((item: AdminUserPreview) => item.role === "company" && item.verificationStatus !== "verified").length;
  const draftJobs = jobs.filter((item: AdminManagedJobPreview) => item.status === "draft").length;
  const pausedJobs = jobs.filter((item: AdminManagedJobPreview) => item.status === "paused").length;
  const pendingVerifications = verifications.filter((item: AdminVerificationRecord) => item.status === "pending").length;
  const failedRetention = errors.filter((item: AdminErrorRecord) => item.source === "retention").length;
  const reportedChats = chats.filter((item: AdminChatRecord) => item.reportsCount > 0 || item.status === "pending_review").length;
  const pendingInvites = invites.filter((item: AdminInviteRecord) => item.status === "pending").length;
  const activeSessionsTotal = sessions.filter((item: AdminSessionRecord) => !item.revokedAt && new Date(item.expiresAt).getTime() > Date.now()).length;
  const activeChatsTotal = chats.filter((item: AdminChatRecord) => item.status === "active").length;
  const pendingReviewChatsTotal = chats.filter((item: AdminChatRecord) => item.status === "pending_review").length;

  const payload = {
    ok: true,
    metrics: {
      ...overview.metrics,
      activeSessionsTotal,
      pendingInvitesTotal: pendingInvites,
      activeChatsTotal,
      pendingReviewChatsTotal,
      verificationPendingTotal: pendingVerifications,
      failedRetentionTotal: failedRetention,
      reportedChatsTotal: reportedChats,
    },
    tasks: buildAdminTasks({
      privateCandidates,
      unverifiedCompanies,
      draftJobs,
      pausedJobs,
      pendingVerifications,
      failedRetention,
      reportedChats,
      pendingInvites,
    }),
    chats,
    invites,
    sessions,
    verifications,
    errors,
    activities,
    trafficSeries: trafficAnalytics.trafficSeries,
    deviceBreakdown: trafficAnalytics.deviceBreakdown,
    referrerBreakdown: trafficAnalytics.referrerBreakdown,
    recentUsers: overview.recentUsers,
    recentJobs: overview.recentJobs,
  };

  const requestActivities = activities.filter((item) => item.type === "api_request");
  void archiveAdminTaskSnapshot({
    generatedAt: new Date().toISOString(),
    tasks: payload.tasks,
    activities: requestActivities,
  });
  void archiveAdminRequestActivities(requestActivities);

  return payload;
}
