import { Prisma } from "@prisma/client";
import { prisma } from "@/lib/server/db";
import { readRecentAdminErrorEntries } from "@/backend/lib-server/admin-ops-storage";
import type { AdminErrorRecord } from "@/types/admin";

function parseJsonRecord(value: string | null | undefined) {
  if (!value) {
    return null;
  }

  try {
    const parsed = JSON.parse(value) as Record<string, unknown>;
    return parsed && typeof parsed === "object" ? parsed : null;
  } catch {
    return null;
  }
}

export async function listAdminErrors(): Promise<AdminErrorRecord[]> {
  const [retentionRows, chatRows, fileLoggedErrors, apiFailures] = await Promise.all([
    prisma.retentionTask.findMany({
      where: {
        OR: [{ status: "failed" }, { status: "retry" }],
      },
      orderBy: { createdAt: "desc" },
      take: 10,
    }),
    prisma.$queryRaw<Array<{
      id: string;
      eventType: string;
      createdAt: Date;
      detailsJson: string | null;
      conversationId: string | null;
    }>>(Prisma.sql`
      SELECT
        id,
        event_type AS "eventType",
        created_at AS "createdAt",
        details_json AS "detailsJson",
        conversation_id AS "conversationId"
      FROM chat_moderation_events
      WHERE event_type = 'report' OR event_type = 'manual_review'
      ORDER BY created_at DESC
      LIMIT 10
    `),
    readRecentAdminErrorEntries(20),
    prisma.event.findMany({
      where: {
        type: "api_request",
      },
      orderBy: { happenedAt: "desc" },
      take: 20,
      select: {
        id: true,
        metadataJson: true,
        happenedAt: true,
        pathname: true,
      },
    }),
  ]);

  const retentionErrors: AdminErrorRecord[] = retentionRows.map((row) => ({
    id: row.id,
    source: "retention",
    title: `Retention task ${row.kind}`,
    detail: row.lastError ?? "Tarea en retry o fallo sin detalle adicional.",
    statusCode: row.status === "failed" ? 503 : 409,
    severity: row.status === "failed" ? "high" : "medium",
    createdAt: row.createdAt.toISOString(),
    href: "/admin/errors",
  }));

  const chatErrors: AdminErrorRecord[] = chatRows.map((row) => ({
    id: row.id,
    source: "chat",
    title: row.eventType === "report" ? "Chat reportado" : "Chat en revisión manual",
    detail: row.detailsJson ?? "Evento de moderación sin detalle adicional.",
    statusCode: row.eventType === "report" ? 409 : 503,
    severity: "high",
    createdAt: row.createdAt.toISOString(),
    href: "/admin/chats",
  }));

  const systemErrors: AdminErrorRecord[] = apiFailures.flatMap((row) => {
    const metadata = parseJsonRecord(row.metadataJson);
    const statusCode = typeof metadata?.statusCode === "number" ? metadata.statusCode : null;
    if (statusCode == null || statusCode < 500) {
      return [];
    }

    return [{
      id: row.id,
      source: "system" as const,
      title: "API failure",
      detail: typeof metadata?.requestUrl === "string" ? metadata.requestUrl : row.pathname ?? "Request without path",
      statusCode,
      severity: "high" as const,
      createdAt: row.happenedAt.toISOString(),
      href: "/admin/tasks",
    }];
  });

  return [...retentionErrors, ...chatErrors, ...systemErrors, ...fileLoggedErrors]
    .sort((left, right) => new Date(right.createdAt).getTime() - new Date(left.createdAt).getTime())
    .slice(0, 20);
}
