import { prisma } from "@/lib/server/db";
import type { AdminBreakdownItem, AdminTrafficPoint } from "@/types/admin";

function buildDayLabel(date: Date) {
  return date.toLocaleDateString("en-US", { weekday: "short", timeZone: "UTC" });
}

function getReferrerLabel(rawReferrer: string | null, source: string | null) {
  if (rawReferrer) {
    try {
      const parsed = new URL(rawReferrer);
      return parsed.hostname.replace(/^www\./, "") || "Direct";
    } catch {
      return rawReferrer;
    }
  }

  return source || "Direct";
}

function buildSeriesSeed() {
  return Array.from({ length: 7 }, (_item, index) => {
    const date = new Date();
    date.setUTCHours(0, 0, 0, 0);
    date.setUTCDate(date.getUTCDate() - (6 - index));
    return {
      dateKey: date.toISOString().slice(0, 10),
      label: buildDayLabel(date),
      total: 0,
      uniqueKeys: new Set<string>(),
    };
  });
}

export async function getAdminTrafficAnalytics(): Promise<{
  trafficSeries: AdminTrafficPoint[];
  deviceBreakdown: AdminBreakdownItem[];
  referrerBreakdown: AdminBreakdownItem[];
}> {
  const from = new Date();
  from.setUTCDate(from.getUTCDate() - 6);
  from.setUTCHours(0, 0, 0, 0);

  const events = await prisma.event.findMany({
    where: {
      type: "api_request",
      happenedAt: { gte: from },
    },
    orderBy: { happenedAt: "asc" },
    select: {
      userId: true,
      sessionId: true,
      source: true,
      pathname: true,
      referrer: true,
      deviceType: true,
      happenedAt: true,
    },
  });

  const seeds = buildSeriesSeed();
  const seriesMap = new Map(seeds.map((item) => [item.dateKey, item]));
  const deviceBreakdownMap = new Map<string, number>();
  const referrerBreakdownMap = new Map<string, number>();

  for (const event of events) {
    const dateKey = event.happenedAt.toISOString().slice(0, 10);
    const bucket = seriesMap.get(dateKey);
    if (!bucket) {
      continue;
    }

    bucket.total += 1;
    bucket.uniqueKeys.add(
      event.sessionId ??
        event.userId ??
        `${event.deviceType ?? "unknown"}:${event.pathname ?? "unknown"}:${event.source ?? "unknown"}`,
    );

    const deviceLabel = event.deviceType ?? "unknown";
    deviceBreakdownMap.set(deviceLabel, (deviceBreakdownMap.get(deviceLabel) ?? 0) + 1);

    const referrerLabel = getReferrerLabel(event.referrer, event.source);
    referrerBreakdownMap.set(referrerLabel, (referrerBreakdownMap.get(referrerLabel) ?? 0) + 1);
  }

  return {
    trafficSeries: seeds.map((item) => ({
      label: item.label,
      total: item.total,
      unique: item.uniqueKeys.size,
    })),
    deviceBreakdown: [...deviceBreakdownMap.entries()]
      .map(([label, value]) => ({ label, value }))
      .sort((left, right) => right.value - left.value),
    referrerBreakdown: [...referrerBreakdownMap.entries()]
      .map(([label, value]) => ({ label, value }))
      .sort((left, right) => right.value - left.value)
      .slice(0, 6),
  };
}
