import { Prisma } from "@prisma/client";
import { prisma } from "@/lib/server/db";

function buildMessageAad(conversationId: string, messageId: string, senderUserId: string) {
  return `chat:${conversationId}:${messageId}:${senderUserId}`;
}

export async function getAdminChatConversation(conversationId: string) {
  const [conversationRows, messageRows] = await Promise.all([
    prisma.$queryRaw<Array<{
      id: string;
      status: "active" | "closed" | "pending_review";
      applicationId: string;
      companyName: string | null;
      candidateName: string | null;
    }>>(Prisma.sql`
      SELECT
        c.id,
        c.status,
        c.application_id AS "applicationId",
        COALESCE(cp."companyName", cu."displayName") AS "companyName",
        COALESCE(pp.nombre, pu."displayName") AS "candidateName"
      FROM chat_conversations c
      INNER JOIN "User" cu ON cu.id = c.company_user_id
      INNER JOIN "Profile" cp ON cp."userId" = cu.id
      INNER JOIN "User" pu ON pu.id = c.candidate_user_id
      INNER JOIN "Profile" pp ON pp."userId" = pu.id
      WHERE c.id = ${conversationId}
      LIMIT 1
    `),
    prisma.$queryRaw<Array<{
      id: string;
      conversationId: string;
      senderUserId: string;
      senderRole: "candidate" | "company";
      messageKind: "user" | "system" | "auto_intro";
      ciphertext: string;
      iv: string;
      authTag: string;
      keyVersion: number;
      createdAt: Date;
    }>>(Prisma.sql`
      SELECT
        id,
        conversation_id AS "conversationId",
        sender_user_id AS "senderUserId",
        sender_role AS "senderRole",
        message_kind AS "messageKind",
        ciphertext,
        iv,
        auth_tag AS "authTag",
        key_version AS "keyVersion",
        created_at AS "createdAt"
      FROM chat_messages
      WHERE conversation_id = ${conversationId}
      ORDER BY created_at ASC
    `),
  ]);

  const conversation = conversationRows[0];
  if (!conversation) {
    return null;
  }

  const { decryptMessage } = await import("@/backend/lib-server/chat-crypto");

  return {
    ...conversation,
    messages: messageRows.map((row) => ({
      id: row.id,
      senderUserId: row.senderUserId,
      senderRole: row.senderRole,
      messageKind: row.messageKind,
      body: decryptMessage(
        {
          ciphertext: row.ciphertext,
          iv: row.iv,
          authTag: row.authTag,
          keyVersion: row.keyVersion,
        },
        buildMessageAad(row.conversationId, row.id, row.senderUserId),
      ),
      createdAt: row.createdAt.toISOString(),
    })),
  };
}
